package com.greenocean.backend;
import com.greenocean.backend.professional.service.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.context.annotation.Import;import org.springframework.beans.factory.annotation.Autowired;import org.junit.jupiter.api.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional @Import(PhaseP2PaymentsTest.Providers.class)
class PhaseP3PaidTest extends PhaseP3Fixtures {
 @Autowired PhaseP2PaymentsTest.SyntheticProvider provider;
 @BeforeEach void paid(){provider.mismatch=false;commerce.change(learner.id(),appointment,new ClinicCommerce.Change(1,"CANCEL","Replace with synthetic paid fixture"));db.update("INSERT INTO clinic_release_approvals(country_code,mode,purpose,evidence_reference,approved_by,expires_at) VALUES('IR','TEXT','PAYMENT_PROVIDER','SYNTHETIC-P3-PAYMENT-NOT-REAL-APPROVAL',?,CURRENT_TIMESTAMP+INTERVAL '1 day')",issuer.id());UUID slot=db.queryForObject("INSERT INTO professional_availability_slots(id,professional_user_id,starts_at,ends_at,consultation_mode,status,governed,price_units) VALUES(uuidv7(),?,CURRENT_TIMESTAMP-INTERVAL '1 minute',CURRENT_TIMESTAMP+INTERVAL '29 minutes','TEXT','BOOKED',TRUE,10000) RETURNING id",UUID.class,author.id());appointment=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,availability_slot_id,scheduled_at,ends_at,consultation_mode,status,clinic_governed,booking_key,price_units,commission_units,provider_fee_units,currency,policy_id,terms_snapshot,payment_deadline) SELECT ?,?,id,starts_at,ends_at,'TEXT','PAYMENT_PENDING',TRUE,uuidv7(),10000,1000,100,'IRR',?,'Synthetic accepted integer snapshot',CURRENT_TIMESTAMP+INTERVAL '5 minutes' FROM professional_availability_slots WHERE id=? RETURNING id",UUID.class,learner.id(),author.id(),policy,slot);db.update("INSERT INTO clinic_invoices(appointment_id,amount_units,currency) VALUES(?,10000,'IRR')",appointment);}
 void capture(){commerce.payment(learner.id(),appointment);commerce.reconcile(issuer.id(),appointment);}
 void completePaid(){capture();UUID id=active();care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Synthetic patient text participation");care.message(author.id(),author.session(),id,UUID.randomUUID(),"Synthetic professional text participation");care.stop(learner.id(),learner.session(),id,"PARTICIPANT_ENDED");care.acknowledge(author.id(),author.session(),id);care.acknowledge(learner.id(),learner.session(),id);}
 @Test void failedOrMissingPaymentCannotActivatePaidCare(){consent();assertThatThrownBy(()->care.enter(learner.id(),learner.session(),appointment)).isInstanceOf(com.greenocean.backend.common.exception.ConflictException.class);assertThat(db.queryForObject("SELECT count(*) FROM clinic_financial_events WHERE appointment_id=?",Integer.class,appointment)).isZero();}
 @Test void serviceEvidenceAccruesAgreedCommissionAndNetPayableOnlyOnce(){capture();assertThat(db.queryForObject("SELECT count(*) FROM clinic_financial_events WHERE appointment_id=? AND kind IN('PLATFORM_FEE','PROFESSIONAL_PAYABLE')",Integer.class,appointment)).isZero();UUID id=active();care.message(learner.id(),learner.session(),id,UUID.randomUUID(),"Synthetic patient participation");care.message(author.id(),author.session(),id,UUID.randomUUID(),"Synthetic professional participation");care.stop(learner.id(),learner.session(),id,"PARTICIPANT_ENDED");care.acknowledge(author.id(),author.session(),id);care.acknowledge(learner.id(),learner.session(),id);care.acknowledge(learner.id(),learner.session(),id);assertThat(db.queryForObject("SELECT amount_units FROM clinic_financial_events WHERE appointment_id=? AND kind='PLATFORM_FEE'",Long.class,appointment)).isEqualTo(1000L);assertThat(db.queryForObject("SELECT amount_units FROM clinic_financial_events WHERE appointment_id=? AND kind='PROFESSIONAL_PAYABLE'",Long.class,appointment)).isEqualTo(8900L);assertThat(commerce.finances(author.id(),true).toString()).contains("net_due_units=8900");}
 @Test void cancellationBeforeDeliveryCannotCreateNegativeUnearnedFees(){capture();commerce.change(author.id(),appointment,new ClinicCommerce.Change(2,"CANCEL","Synthetic professional cancellation before delivery"));commerce.requestRefund(issuer.id(),appointment);commerce.reconcileRefund(issuer.id(),appointment);assertThat(db.queryForObject("SELECT count(*) FROM clinic_financial_events WHERE appointment_id=? AND kind IN('COMMISSION_REVERSAL','PAYABLE_REVERSAL')",Integer.class,appointment)).isZero();assertThat(commerce.finances(author.id(),true).toString()).contains("net_due_units=0");}
 @Test void confirmedRefundReversesOnlyActuallyEarnedCommissionAndPayable(){completePaid();commerce.dispute(learner.id(),appointment,"Synthetic post-service refund review");commerce.resolve(issuer.id(),appointment,true,"Synthetic independent full refund decision");assertThat(commerce.finances(author.id(),true).toString()).contains("held_units=8900");commerce.requestRefund(issuer.id(),appointment);commerce.reconcileRefund(issuer.id(),appointment);assertThat(db.queryForObject("SELECT amount_units FROM clinic_financial_events WHERE appointment_id=? AND kind='COMMISSION_REVERSAL'",Long.class,appointment)).isEqualTo(1000L);assertThat(commerce.finances(author.id(),true).toString()).contains("net_due_units=0");}
}
